for (size_t i = 0; i < segments.size(); ++i) {
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& s1 = segments[i];
        const Segment2d& s2 = segments[j];

        Point2d p1 = s1.p1();
        Point2d p2 = s1.p2();
        Point2d p3 = s2.p1();
        Point2d p4 = s2.p2();

        double x1 = p1.x();
        double y1 = p1.y();
        double x2 = p2.x();
        double y2 = p2.y();
        double x3 = p3.x();
        double y3 = p3.y();
        double x4 = p4.x();
        double y4 = p4.y();

        double denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);
        double numA = (x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3);
        double numB = (x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3);

        if (std::abs(denom) < 1e-9) {
            // Parallel or collinear
            // Check for overlapping collinear segments
            if (std::abs(numA) < 1e-9 && std::abs(numB) < 1e-9) {
                // Collinear: check if endpoints lie on the other segment
                Point2d pts[4] = {p1, p2, p3, p4};
                for (int k = 0; k < 4; ++k) {
                    const Segment2d& seg = (k < 2) ? s2 : s1;
                    Point2d a = seg.p1();
                    Point2d b = seg.p2();
                    if (pts[k].x() >= std::min(a.x(), b.x()) - 1e-9 && 
                        pts[k].x() <= std::max(a.x(), b.x()) + 1e-9 &&
                        pts[k].y() >= std::min(a.y(), b.y()) - 1e-9 && 
                        pts[k].y() <= std::max(a.y(), b.y()) + 1e-9) {
                        intersections.push_back(pts[k]);
                    }
                }
            }
            continue;
        }

        double uA = numA / denom;
        double uB = numB / denom;

        if (uA >= 0.0 && uA <= 1.0 && uB >= 0.0 && uB <= 1.0) {
            intersections.push_back(Point2d(x1 + uA * (x2 - x1), y1 + uA * (y2 - y1)));
        }
    }
}
return intersections;

